    root.querySelectorAll('i[data-i]').forEach(function (el) {
      var t = document.createElement('span');
      t.innerHTML = svgIcon(el.getAttribute('data-i'), el.className);
      el.replaceWith(t.firstChild);
    });
    root.querySelectorAll('input[data-ind]').forEach(function (i) { i.indeterminate = true; });
    // grupo de escolha única: segmentado, tabs, view switcher, paginação, chips
    root.querySelectorAll('[data-lu-single]').forEach(function (g) {
      g.addEventListener('click', function (e) {
        var b = e.target.closest('button,[role=tab],a');
        if (!b || !g.contains(b) || b.disabled) return;
        if (b.closest('[data-lu-single]') !== g) return;
        g.querySelectorAll(':scope > button, :scope > [role=tab], :scope > a').forEach(function (x) {
          x.classList.toggle('on', x === b);
          if (x.hasAttribute('aria-selected')) x.setAttribute('aria-selected', x === b ? 'true' : 'false');
          if (x.hasAttribute('aria-pressed')) x.setAttribute('aria-pressed', x === b ? 'true' : 'false');
        });
        g.dispatchEvent(new CustomEvent('lk:change', { detail: b.getAttribute('data-v') || b.textContent.trim(), bubbles: true }));
      });
    });
    // alternância simples (chips de filtro, estrela, curtir)
    root.querySelectorAll('[data-lu-toggle]').forEach(function (b) {
      b.addEventListener('click', function () {
        b.classList.toggle('on');
        if (b.hasAttribute('aria-pressed')) b.setAttribute('aria-pressed', b.classList.contains('on'));
      });
    });
    // copiar
    root.querySelectorAll('[data-lu-copy]').forEach(function (b) {
      b.addEventListener('click', function () {
        var txt = b.getAttribute('data-lu-copy');
        try { navigator.clipboard && navigator.clipboard.writeText(txt); } catch (e) {}
        var lbl = b.querySelector('.lu-copy-label');
        b.classList.add('done');
        if (lbl) { var old = lbl.textContent; lbl.textContent = 'Copiado'; }
        setTimeout(function () { b.classList.remove('done'); if (lbl) lbl.textContent = old; }, 1400);
      });
    });
    // remover chip
    root.querySelectorAll('[data-lu-remove]').forEach(function (b) {
      b.addEventListener('click', function () { var c = b.closest('.lu-chip,.lu-tag'); if (c) c.remove(); });
    });
    // stepper numérico
    root.querySelectorAll('.lu-stepper').forEach(function (s) {
      var inp = s.querySelector('input');
      s.querySelectorAll('button[data-step]').forEach(function (b) {
        b.addEventListener('click', function () {
          var v = parseFloat(inp.value || '0') + parseFloat(b.getAttribute('data-step'));
          var min = inp.min !== '' ? parseFloat(inp.min) : -Infinity, max = inp.max !== '' ? parseFloat(inp.max) : Infinity;
          inp.value = Math.max(min, Math.min(max, v));
        });
      });
    });
    // rating
    root.querySelectorAll('.lu-rating[data-interactive]').forEach(function (r) {
      var stars = r.querySelectorAll('button');
      stars.forEach(function (s, i) {
        s.addEventListener('click', function () { stars.forEach(function (x, j) { x.classList.toggle('on', j <= i); }); });
      });
    });
    // OTP: avança o foco
    root.querySelectorAll('.lu-otp').forEach(function (o) {
      var ins = o.querySelectorAll('input');
      ins.forEach(function (inp, i) {
        inp.addEventListener('input', function () { if (inp.value && ins[i + 1]) ins[i + 1].focus(); });
      });
    });
    // range: atualiza o preenchimento
    root.querySelectorAll('input.lu-range').forEach(function (r) {
      function upd() { var p = (r.value - r.min) / (r.max - r.min) * 100; r.style.setProperty('--p', p + '%'); var o = r.parentNode.querySelector('output'); if (o) o.textContent = r.getAttribute('data-prefix') ? r.getAttribute('data-prefix') + r.value : r.value; }
      r.addEventListener('input', upd); upd();
    });
