  // ---------- Toaster ao vivo: empilha, conta o tempo, pausa no hover ----------
  var KINDS = { neutral: ['c-neutral', 'info'], info: ['c-info', 'info'], success: ['c-success', 'check-circle'], warning: ['c-warning', 'alert'], error: ['c-error', 'x-circle'], loading: ['c-primary', null] };
